<?php
require 'config/database.php';require 'includes/auth.php';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(isset($_GET['hapus'])){try{$s=$pdo->prepare('DELETE FROM perangkat_daerah WHERE id=?');$s->execute([(int)$_GET['hapus']]);}catch(PDOException $x){$error='Dinas tidak dapat dihapus karena masih digunakan oleh data pegawai atau kendaraan.';}if(empty($error)){header('Location: perangkat_daerah.php');exit;}}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$nama=trim($_POST['nama_dinas']);$ket=trim($_POST['keterangan']);try{if($id){$s=$pdo->prepare('UPDATE perangkat_daerah SET nama_dinas=?,keterangan=? WHERE id=?');$s->execute([$nama,$ket,$id]);}else{$s=$pdo->prepare('INSERT INTO perangkat_daerah(nama_dinas,keterangan) VALUES(?,?)');$s->execute([$nama,$ket]);}header('Location: perangkat_daerah.php');exit;}catch(PDOException $x){$error='Gagal menyimpan. Nama dinas harus unik.';}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM perangkat_daerah WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT d.*, (SELECT COUNT(*) FROM kendaraan k WHERE k.perangkat_daerah_id=d.id) jumlah_kendaraan, (SELECT COUNT(*) FROM pegawai p WHERE p.perangkat_daerah_id=d.id) jumlah_pegawai FROM perangkat_daerah d ORDER BY d.nama_dinas')->fetchAll();
$pageTitle='Perangkat Daerah';require 'includes/header.php';
?>
<h3 class="mb-3">Data Perangkat Daerah</h3><?php if(!empty($error)):?><div class="alert alert-warning"><?=e($error)?></div><?php endif;?>
<div class="card shadow-sm mb-4"><div class="card-header bg-white fw-semibold"><?= $edit?'Edit Perangkat Daerah':'Tambah Perangkat Daerah'?></div><div class="card-body"><form method="post" class="row g-3"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="col-md-5"><label class="form-label">Nama Instansi / Dinas</label><input class="form-control" name="nama_dinas" required value="<?=e($edit['nama_dinas']??'')?>"></div><div class="col-md-5"><label class="form-label">Keterangan</label><input class="form-control" name="keterangan" value="<?=e($edit['keterangan']??'')?>"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Simpan</button></div></form></div></div>
<div class="card shadow-sm"><div class="card-body table-responsive"><table class="table table-hover"><thead><tr><th>No</th><th>Nama Dinas</th><th>Keterangan</th><th>Jumlah Kendaraan</th><th>Jumlah Pegawai</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['nama_dinas'])?></td><td><?=e($r['keterangan'])?></td><td><?=$r['jumlah_kendaraan']?></td><td><?=$r['jumlah_pegawai']?></td><td class="text-nowrap"><a class="btn btn-sm btn-warning" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-sm btn-danger" onclick="return confirm('Hapus perangkat daerah?')" href="?hapus=<?=$r['id']?>">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require 'includes/footer.php'; ?>
